CREATE PROCEDURE usp_UpdateOrderStatus
    @orderId INT,
    @newStatus VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @sql NVARCHAR(MAX) = 'UPDATE Orders SET Status = @newStatus WHERE OrderId = @orderId';
    EXEC sp_executesql @sql, N'@orderId INT, @newStatus VARCHAR(50)', @orderId = @orderId, @newStatus = @newStatus;
END
